function vmVind(array $data,string $id):?int{foreach((array)($data['vergaderingen']??[]) as $i=>$v)if(is_array($v)&&($v['id']??'')===$id)return$i;return null;}
function vmGeldigeAanwezigheid(array $ruw,array $leden,string $soort):array{$ids=[];foreach($leden as $l)if(is_array($l)&&($soort==='leden'||ledenIsBestuurslid($l)))$ids[(string)$l['id']]=true;$out=[];foreach($ruw as $id=>$status)if(isset($ids[(string)$id])&&isset(vergaderingenAanwezigheid()[(string)$status]))$out[(string)$id]=(string)$status;return$out;}
$flash=$_SESSION['vergaderingen_flash']??null;unset($_SESSION['vergaderingen_flash']);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){vmFlash('Sessie verlopen.','fout');vmRedirect();}$actie=(string)($_POST['actie']??'');$slot=dataSlotOpen();try{$data=repoVergaderingenLees();
  if($actie==='opslaan'){$id=trim((string)($_POST['id']??''));$idx=$id===''?null:vmVind($data,$id);$bestaand=$idx===null?null:$data['vergaderingen'][$idx];$soort=$bestaand['soort']??($_POST['soort']??'bestuur');if(!isset(vergaderingenSoorten()[$soort]))$soort='bestuur';$leden=array_values(array_filter((array)(ledenServiceLees()['leden']??[]),static fn($l)=>is_array($l)&&empty($l['gearchiveerd_op'])));$aanwezig=vmGeldigeAanwezigheid((array)($_POST['aanwezigheid']??[]),$leden,$soort);$invoer=['soort'=>$soort,'titel'=>$_POST['titel']??'','datum'=>$_POST['datum']??'','tijd'=>$_POST['tijd']??'','locatie'=>$_POST['locatie']??'','status'=>$_POST['status']??'gepland','ledenvergadering_type'=>$_POST['ledenvergadering_type']??'regulier','agenda_status'=>$_POST['agenda_status']??'concept','notulen_status'=>$_POST['notulen_status']??'concept','agenda'=>$_POST['agenda']??[],'notulen'=>$_POST['notulen']??'','aanwezigheid'=>$aanwezig];$v=vergaderingNormaliseer($invoer,$bestaand);if($idx===null){$v['nummer']=vergaderingVolgendNummer($data,$soort);$v['aangemaakt_door']=$huidigeGebruiker;$data['vergaderingen'][]=$v;}else$data['vergaderingen'][$idx]=$v;if(repoVergaderingenSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'vergadering_opgeslagen',$v['id'].' · '.$soort);vmFlash('Vergadering opgeslagen.');}else vmFlash('Opslaan mislukt.','fout');}
