 }finally{dataSlotDicht($slot);}vmRedirect();
}
$data=repoVergaderingenLees();$lijst=vergaderingenGesorteerd($data);$editId=trim((string)($_GET['edit']??''));$edit=null;if($editId!=='')foreach((array)($data['vergaderingen']??[]) as $x)if(is_array($x)&&($x['id']??'')===$editId){$edit=$x;break;}$nieuwSoort=in_array($_GET['nieuw']??'',['bestuur','leden'],true)?$_GET['nieuw']:'';$toonForm=$edit!==null||$nieuwSoort!=='';$v=$edit??['soort'=>$nieuwSoort?:'bestuur','status'=>'gepland','ledenvergadering_type'=>'regulier','agenda_status'=>'concept','notulen_status'=>'concept','agenda'=>[],'aanwezigheid'=>[]];$leden=array_values(array_filter((array)(ledenServiceLees()['leden']??[]),static fn($l)=>is_array($l)&&empty($l['gearchiveerd_op'])));$aanwezigen=(($v['soort']??'bestuur')==='bestuur')?array_values(array_filter($leden,'ledenIsBestuurslid')):$leden;$agenda=(array)($v['agenda']??[]);$agenda[]=['onderwerp'=>'','indiener'=>'','toelichting'=>'','besluit'=>''];
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Vergaderingen</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1150px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.veld label{display:block;font-weight:700;margin-bottom:5px}.veld input,.veld select,.veld textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px;font:inherit}.veld textarea{min-height:100px}.btn{display:inline-block;border:1px solid #d3ccb7;background:#fff;color:#2d6260;border-radius:8px;padding:9px 12px;text-decoration:none;font:inherit;font-weight:750;cursor:pointer}.btn.primary{background:#3a7a77;color:#fff;border:0}.btn.danger{background:#fff0ed;color:#8b2e27}.actions{display:flex;gap:8px;flex-wrap:wrap}.melding{padding:12px;border-radius:8px;background:#eaf6ee}.melding.fout{background:#fdeceb;color:#8b2e27}.meta{color:#68705f;font-size:13px}.agenda{border-top:1px solid #eee9db;padding-top:12px;margin-top:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Vergaderingen</h1><div class="actions"><a class="btn primary" href="?nieuw=bestuur">+ Bestuursvergadering</a><a class="btn primary" href="?nieuw=leden">+ Ledenvergadering / ALV</a></div><?php if($flash):?><div class="melding <?=vmEsc($flash['type']??'')?>"><?=vmEsc($flash['tekst']??'')?></div><?php endif;?><?php if($toonForm):?><section class="card"><h2><?=vmEsc($edit?'Vergadering bewerken':'Nieuwe '.vergaderingenSoorten()[$v['soort']])?></h2><form method="post"><input type="hidden" name="csrf" value="<?=vmEsc($csrfToken)?>"><input type="hidden" name="actie" value="opslaan"><input type="hidden" name="id" value="<?=vmEsc($edit['id']??'')?>"><input type="hidden" name="soort" value="<?=vmEsc($v['soort'])?>"><div class="grid"><div class="veld"><label>Titel</label><input name="titel" maxlength="120" value="<?=vmEsc($v['titel']??'')?>"></div><div class="veld"><label>Datum</label><input type="date" name="datum" value="<?=vmEsc($v['datum']??'')?>"></div><div class="veld"><label>Tijd</label><input name="tijd" value="<?=vmEsc($v['tijd']??'')?>"></div><div class="veld"><label>Locatie</label><input name="locatie" maxlength="120" value="<?=vmEsc($v['locatie']??'')?>"></div><div class="veld"><label>Status</label><select name="status"><?php foreach(vergaderingenStatussen() as $k=>$lab):?><option value="<?=vmEsc($k)?>" <?=($v['status']??'')===$k?'selected':''?>><?=vmEsc($lab)?></option><?php endforeach;?></select></div><?php if($v['soort']==='leden'):?><div class="veld"><label>Type</label><select name="ledenvergadering_type"><?php foreach(vergaderingenLedenTypes() as $k=>$lab):?><option value="<?=vmEsc($k)?>" <?=($v['ledenvergadering_type']??'')===$k?'selected':''?>><?=vmEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Agenda status</label><select name="agenda_status"><?php foreach(vergaderingDocumentStatussen() as $k=>$lab):?><option value="<?=vmEsc($k)?>" <?=($v['agenda_status']??'')===$k?'selected':''?>><?=vmEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Notulen status</label><select name="notulen_status"><?php foreach(vergaderingDocumentStatussen() as $k=>$lab):?><option value="<?=vmEsc($k)?>" <?=($v['notulen_status']??'')===$k?'selected':''?>><?=vmEsc($lab)?></option><?php endforeach;?></select></div><?php endif;?></div><h3>Agenda</h3><?php foreach($agenda as $i=>$p):?><div class="agenda grid"><div class="veld">