rwijderen?');"><input type="hidden" name="csrf" value="<?=vmEsc($csrfToken)?>"><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="id" value="<?=vmEsc($item['id']??'')?>"><button class="btn danger" type="submit">Verwijderen</button></form></div></div><?php endforeach;?></section></main></body></html>
